window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-28"]={"date": "2026-08-28", "dateKR": "2026년 8월 28일", "dateEN": "28 August 2026", "total": 86, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "한국, 세계 첫 '녹색해운항로' 전용 법제화 추진", "eTitle": "South Korea puts green shipping corridors into law", "src": "Splash247", "date": "2026-08-27", "kSum": "해양수산부가 녹색해운항로 개발을 규율하는 세부 규칙을 공표하며, 양자 간 약속에 머물던 녹색해운항로를 국내법으로 전환한다고 밝혔다. 서울은 이를 녹색해운항로 개발을 다루는 세계 최초의 전용 법제라고 주장한다.", "eSum": "", "kImp": "한국 해운·조선 업계에 직접적인 규제 프레임을 제공하고, 탈탄소 항로 구축의 제도적 기반을 마련해 향후 국제 표준 논의에서 선도적 위치를 노린다.", "eImp": "", "url": "https://splash247.com/south-korea-puts-green-shipping-corridors-into-law/"}, {"code": "TOP", "title": "중국 컨테이너 선사, 운임 급등에 실적 급증 전망", "eTitle": "Chinese Container Liners Head for Profit Jump as Rates Surge", "src": "gCaptain", "date": "2026-08-27", "kSum": "관세 변화를 앞둔 밀어내기 수요와 지속적인 해운 교란으로 컨테이너 운임이 2년 만에 최고치로 오르면서 중국 컨테이너 선사들이 실적 급증을 앞두고 있다. 드루리 세계컨테이너지수는 2분기 중 40피트당 4,639달러로 정점을 찍었다.", "eSum": "", "kImp": "미국 관세를 피하려는 조기 성수기 수요와 지정학 리스크가 운임을 끌어올려 선사 수익성이 개선되고 있음을 보여주며, 하반기 컨테이너 시황의 방향을 가늠하는 지표가 된다.", "eImp": "", "url": "https://gcaptain.com/chinese-container-liners-head-for-profit-jump-as-rates-surge/"}, {"code": "TOP", "title": "캐나다, 데이비(Davie)에 쇄빙선 6척 113억 캐나다달러 사상 최대 건조계약 부여", "eTitle": "Canada Awards Quebec's Largest Shipbuilding Project for Arctic Icebreakers", "src": "The Maritime Executive", "date": "2026-08-24", "kSum": "캐나다 정부가 퀘벡 레비의 데이비 조선소에 캐나다 해안경비대용 프로그램 쇄빙선 6척을 건조하는 113억 캐나다달러 규모 고정가 계약을 부여했다. 퀘벡 역사상 최대 조선 계약으로, 첫 선박 건조는 2027년 시작되며 2030년대에 걸쳐 인도된다.", "eSum": "", "kImp": "북극 안보·항로 확보를 겨냥한 대규모 쇄빙선 투자로, 국가조선전략(NSS) 하에서 캐나다 조선 역량과 북극 해양 주권 강화를 상징한다.", "eImp": "", "url": "https://maritime-executive.com/article/canada-awards-quebec-s-largest-shipbuilding-project-for-arctic-icebreakers"}, {"code": "TOP", "title": "IAEA, 선박 원자력 추진 복귀 위한 글로벌 이니셔티브 'ATLAS' 출범", "eTitle": "IAEA launches global push to bring nuclear power back to sea", "src": "Splash247", "date": "2026-08-27", "kSum": "국제원자력기구(IAEA)가 민간 해운에 원자력 추진을 다시 도입하기 위한 규제·안전 프레임을 만드는 글로벌 이니셔티브 'ATLAS(Atomic Technologies Licensed for Applications at Sea)'를 출범했다.", "eSum": "", "kImp": "무탄소 대체 추진 옵션으로서 선박 원자력의 제도적 논의가 국제기구 차원에서 본격화됐음을 의미하며, 장기 탈탄소 로드맵에 새로운 변수를 더한다.", "eImp": "", "url": "https://splash247.com/iaea-launches-global-push-to-bring-nuclear-power-back-to-sea/"}, {"code": "TOP", "title": "토탈에너지스(TotalEnergies), 아틱 LNG 2 지분 완전 정리", "eTitle": "TotalEnergies cuts final ties with Arctic LNG 2", "src": "Splash247", "date": "2026-08-27", "kSum": "프랑스 에너지 대기업 토탈에너지스가 노바텍의 아틱 LNG 2 프로젝트 지분 10%를 노바텍 자회사 노드라인(NordLine)에 이전 완료하며 해당 프로젝트와의 관계를 완전히 끊었다고 밝혔다.", "eSum": "", "kImp": "제재 대상 러시아 LNG 프로젝트에서 서방 메이저의 완전 철수를 보여주며, 글로벌 LNG 공급망과 러시아산 가스 물동량 재편에 영향을 준다.", "eImp": "", "url": "https://splash247.com/totalenergies-cuts-final-ties-with-arctic-lng-2/"}, {"code": "TOP", "title": "DNV, \"잘못된 연료 선택에도 견디는 선대를 구축하라\"", "eTitle": "DNV: Build fleets that can survive the wrong fuel call", "src": "Splash247", "date": "2026-08-27", "kSum": "DNV의 최신 '해양전망 2050(Maritime Forecast to 2050)' 보고서는 선사들이 단일 탈탄소 경로에 베팅하지 말고, 규제·연료·기술이 급변해도 살아남을 수 있는 유연한 전략을 세워야 한다고 권고했다.", "eSum": "", "kImp": "연료 전환 불확실성이 큰 상황에서 신조·투자 의사결정의 리스크 관리 기준을 제시하며, 선사의 장기 선대 계획 수립에 참고가 된다.", "eImp": "", "url": "https://splash247.com/dnv-build-fleets-that-can-survive-the-wrong-fuel-call/"}, {"code": "TOP", "title": "외르스테드(Ørsted), 한국 1.4GW 해상풍력 프로젝트 보류", "eTitle": "Ørsted puts 1.4GW South Korean offshore wind project on hold", "src": "Splash247", "date": "2026-08-27", "kSum": "덴마크 해상풍력 개발사 외르스테드가 한국에서 추진하던 1.4GW 규모 해상풍력 프로젝트 입찰 참여를 중단(보류)했다.", "eSum": "", "kImp": "한국 해상풍력 시장의 사업성·정책 여건에 대한 글로벌 개발사의 신중론을 보여주며, 국내 해상풍력 및 관련 설치·서비스 선박 수요 전망에 영향을 준다.", "eImp": "", "url": "https://splash247.com/orsted-puts-1-4gw-south-korean-offshore-wind-project-on-hold/"}, {"code": "TOP", "title": "컨테이너 해운, 화재예방을 '선적·부킹 단계'로 앞당겨야", "eTitle": "Container shipping urged to move fire prevention upstream", "src": "Splash247", "date": "2026-08-27", "kSum": "컨테이너 해운업계가 위험 화물 리스크를 사고 발생 이후가 아니라 예약(부킹) 단계에서 식별하는 등 화재예방을 상류 공정으로 대폭 앞당겨야 한다는 지적이 제기됐다.", "eSum": "", "kImp": "잇단 컨테이너선 화재 이후 미신고·오신고 위험물 관리가 핵심 과제로 부상했으며, 화물 예약·검증 시스템 개선의 필요성을 부각한다.", "eImp": "", "url": "https://splash247.com/container-shipping-urged-to-move-fire-prevention-upstream/"}, {"code": "TOP", "title": "이란 블랙리스트, 호르무즈 셔틀탱커 '생명줄' 위협", "eTitle": "Iran blacklist threatens Hormuz shuttle tanker lifeline", "src": "Splash247", "date": "2026-08-27", "kSum": "호르무즈 해협을 통해 중동 원유를 실어 나른 뒤 환적하는, 갈수록 중요해진 셔틀탱커 무역이 이란 관련 블랙리스트(제재) 확대로 위협받고 있다.", "eSum": "", "kImp": "호르무즈 위기 속에서 원유 물류의 대체 통로로 부상한 셔틀탱커 운항이 제재 리스크에 노출되며, 중동발 원유 공급망과 탱커 시황에 파급 효과가 예상된다.", "eImp": "", "url": "https://splash247.com/iran-blacklist-threatens-hormuz-shuttle-tanker-lifeline/"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "벌크선 오션 위너(Ocean Winner), 인도 동해안서 침몰…22명 실종", "eTitle": "Bulk Carrier Ocean Winner Sinks Off India, 22 Crew Missing", "src": "gCaptain", "date": "2026-08-23", "kSum": "철광석 약 7만1천톤을 싣고 인도 파라딥항을 출항해 중국으로 향하던 파나마 선적 벌크선 오션 위너(72,928 DWT)가 8월 22일 파라딥 동쪽 약 240해리 해상에서 침몰했다. 선박은 금요일 경사(list)가 발생한 뒤 8분 만에 침몰했고, 승선 24명 중 중국인 2명만 구조돼 22명이 실종됐다. 인도 해안경비대와 해군이 수색을 이어갔다.", "eSum": "", "kCause": "금요일 급격한 경사 발생 직후 단시간 내 침몰. 정확한 원인은 발표되지 않았으며 화물(철광석) 액상화·이동 또는 복원성 상실 가능성이 제기된다. (추정)", "eCause": "", "kLes": "급속 경사·단시간 침몰 위험에 대비한 화물 적재·복원성 관리와, 신속한 조난경보 발신 및 퇴선 체계의 중요성을 재확인시킨다. (추정)", "eLes": "", "url": "https://gcaptain.com/search-continues-for-22-after-bulk-carrier-sinks-off-india/"}, {"code": "ACC", "title": "아프라막스 유조선, 호르무즈 인근 오만 해역서 피격·항행불능", "eTitle": "Tanker Hit and Disabled Near Strait of Hormuz", "src": "The Maritime Executive", "date": "2026-08-24", "kSum": "8월 24일(현지 월요일 밤) 오만 무산담 반도 동쪽, 호르무즈 해협 오만 연안 항로에서 유조선이 정체불명 발사체에 피격됐다. 약 2025 UTC 선장이 피격을 보고했으며 기관실이 손상돼 선박이 항행불능 상태가 됐다. 선원은 안전하며 환경영향은 미확인이다. (외신은 라이베리아 선적 아프라막스 Metro Venetian으로 보도)", "eSum": "", "kCause": "호르무즈 해협 분쟁과 관련한 정체불명 발사체 피격으로 기관실이 손상됨. (추정)", "eCause": "", "kLes": "분쟁 수역 통항 시 위협 평가·회피 항로 설정, 기관실 방호 및 피격 후 조난·예인 대응 체계 강화가 필요하다.", "eLes": "", "url": "https://maritime-executive.com/article/tanker-hit-and-disabled-near-strait-of-hormuz"}, {"code": "ACC", "title": "예인선 SL 수알 1(SL Sual 1), 잠발레스 인양 예항 중 전복·침몰", "eTitle": "Tug Capsizes and Sinks During Salvage Tow off Zambales", "src": "The Maritime Executive", "date": "2026-08-24", "kSum": "필리핀 잠발레스 보톨란 해역에서 재부양된 예인선 MTUG SL 수알 1이 8월 24일 오전 예항 도중 우현으로 서서히 기울다 수심 약 24m 해역에 완전히 침몰했다. 인양작업자 10명이 바다로 뛰어내려 전원 구조됐다. 선박에는 디젤 약 1만5천 리터가 실려 있어 유류 유출이 우려됐다.", "eSum": "", "kCause": "이 예인선은 8월 14일 강한 파도로 처음 기울며 해수가 유입됐고, 예항 중 수중 금속 잔해·장애물 충돌 여부와 거친 해상이 침몰을 악화시켰는지 당국이 조사 중이다. (추정)", "eCause": "", "kLes": "손상 선박의 재부양·예항 시 잔존 침수·복원성 평가, 기상·해상 상태 확인, 유류 유출 대비 방제 장비 사전 배치가 중요하다.", "eLes": "", "url": "https://maritime-executive.com/article/video-tug-capsizes-during-salvage-tow-off-luzon"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "최근 7일간 신규 소식이 확인되지 않았습니다", "eTitle": "No fresh items in the last 7 days", "src": "—", "date": "2026-08-28", "kSum": "이 기간 신선 기사가 확인되지 않았습니다. 다음 갱신 시 보완됩니다.", "eSum": "No fresh items in the last 7 days.", "kImp": "-", "eImp": "-", "url": "https://brightatsea-alt.github.io/maritime-daily-digest/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "코스코 특수운송(COSCO Shipping Specialised Carriers), 中 자동차 수출 붐 타고 상반기 매출·순익 급증", "eTitle": "COSCO Shipping Specialised Carriers posts revenue growth in H1 2026", "src": "Baird Maritime", "date": "2026-08-26", "kSum": "코스코 특수운송(COSCO Shipping Specialised Carriers)은 2026년 상반기 매출이 전년 동기 대비 34.07% 증가한 144억5천만 위안(약 21억2천만 달러), 순이익은 66.24% 늘어난 13억7천만 위안을 기록했다고 밝혔다. 6월 말 기준 자사 통제 선대는 206척(총 959만 DWT)으로 상반기에만 11척이 추가됐다. 자동차 운송량은 전년비 63% 증가한 39만4,600대로, 이 중 순수 자동차선(PCC)이 33만3,300대를 실어날랐다.", "eSum": "COSCO Shipping Specialised Carriers reported H1 2026 operating revenue of CNY14.45bn ($2.12bn), up 34.07% year-on-year, with net profit surging 66.24% to CNY1.37bn. Its controlled fleet grew to 206 vessels (9.59m DWT) with 11 new ships added in the half. Vehicle transport volumes rose 63% YoY to 394,600 units, of which pure car carriers moved 333,300 vehicles.", "kImp": "중국 완성차 수출 급증세가 자국 대형 특수운송 선사의 실적을 견인하고 있음을 보여준다. 선대 확장과 운송량 증가가 동시에 나타나며 중국계 선사의 글로벌 자동차 해상물류 영향력이 커지고 있다.", "eImp": "Confirms that China's vehicle export surge is driving strong earnings for domestic specialised carriers, with simultaneous fleet expansion and volume growth underscoring the rising clout of Chinese operators in global finished-vehicle logistics.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/cosco-shipping-specialised-carriers-posts-revenue-growth-in-h1-2026"}, {"code": "PCTC", "title": "SFL, 2분기 순익 3,400만 달러…3.6억 달러 규모 LNG 자동차선 4척 발주", "eTitle": "SFL Corporation reports $34m second-quarter net income", "src": "Baird Maritime", "date": "2026-08-26", "kSum": "선주사 SFL Corporation이 2분기(6월 말 기준) 매출 약 2억1백만 달러, 순이익 3,400만 달러(주당 0.25달러)를 기록했다. 5월에는 6,500 CEU 자동차선 2척(SFL Conductor·Composer)을 아시아 정기선사에 3년 용선했고, 약 3억6,300만 달러를 들여 7,000 CEU LNG 이중연료 자동차선 4척(2029년 인도)을 신규 발주했다. 이 중 2척은 아시아 완성차 제조사에 5년 용선돼 확정 백로그가 약 1억5천만 달러 늘었다.", "eSum": "Shipowner SFL Corporation reported Q2 operating revenue of about $201m and net income of $34m ($0.25/share). In May it fixed two 6,500 CEU car carriers on three-year charters to an Asian liner, and it ordered four 7,000 CEU LNG dual-fuel car carrier newbuilds (2029 delivery) for roughly $363m, with two already chartered for five years to an Asian carmaker, adding about $150m to firm backlog.", "kImp": "선주·리스 부문에서도 자동차선 신조·장기 용선 투자가 이어지며 PCTC 자산에 대한 금융 수요가 견조함을 보여준다. 장기 확정 용선 구조는 자동차선 시장의 안정적 수익 기대를 뒷받침한다.", "eImp": "Shows continued newbuild and long-term charter investment in car carriers by owner-lessors, reflecting robust financing demand for PCTC assets, with long fixed charters underpinning expectations of stable earnings in the segment.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/sfl-corporation-reports-34m-second-quarter-net-income"}, {"code": "PCTC", "title": "中 조선소, 국내외 자동차선 신조 수주 이어져…하이난 춘룽 5,000 CEU PCTC 건조 착수", "eTitle": "Dry Cargo Vessel News Roundup | August 26 – Chinese yards secure new car carrier orders", "src": "Baird Maritime", "date": "2026-08-26", "kSum": "베어드 마리타임의 8월 26일 건화물선 뉴스 라운드업에 따르면 중국 조선소들이 국내외 고객으로부터 자동차선 신조를 잇달아 수주하고 있다. 장쑤 캉핑 조선소는 하이난 춘룽 국제해운(Hainan Chunlong International Shipping)이 발주한 5,000 CEU급 순수 자동차·트럭선(PCTC) 건조에 착수했으며, 이 선박은 파나마 운하 통과가 가능하고 얕은 흘수로 중소형 항만 기항이 가능하도록 설계됐다. 아울러 회그 오토라이너스의 CMHI 6척 추가 발주도 함께 소개됐다.", "eSum": "Baird Maritime's August 26 dry cargo roundup notes Chinese yards continuing to win car carrier orders from local and overseas customers. Jiangsu Kangping Shipyard has begun construction of a 5,000 CEU PCTC for Hainan Chunlong International Shipping, designed for Panama Canal transits and shallow-draught calls at small and medium ports, alongside coverage of Höegh Autoliners' six-ship order at CMHI.", "kImp": "신규 선주(하이난 춘룽)의 시장 진입과 파나마막스급 소형 PCTC 건조는 중국 자동차 수출 확대에 대응한 선대 다변화 흐름을 보여준다. 중국 조선소가 자국·해외 수요를 모두 흡수하며 자동차선 신조 시장을 주도하고 있다.", "eImp": "The entry of a new owner (Hainan Chunlong) and construction of a Panamax-class smaller PCTC illustrate fleet diversification in response to China's export growth, with Chinese yards absorbing both domestic and overseas demand and dominating car carrier newbuilding.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-august-26-dutch-electric-shortsea-ship-design-norwegian-multi-purpose-carrier-delivery-and-more"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "발레니우스 빌헬름센(Wallenius Wilhelmsen), 배당락 임박… H1 2026 배당 주당 0.61달러", "eTitle": "Income Investors Should Know That Wallenius Wilhelmsen (OB:WAWI) Goes Ex-Dividend Soon", "src": "Simply Wall St", "date": "2026-08-22", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 8월 26일 배당락(ex-dividend)을 앞두고 있으며, 다음 배당금은 주당 0.61달러로 9월 16일 지급된다. 지난 1년 총 배당은 주당 1.15달러로 현재 주가 기준 배당수익률은 약 6.5%다. 배당성향은 순이익의 55%, 잉여현금흐름의 82% 수준으로 프로파일러는 배당이 이익과 현금흐름 양쪽에서 감당 가능하다고 평가했다. 지난 5년간 순이익은 연 25%, 지난 8년간 배당은 연평균 약 33% 증가했다.", "eSum": "Wallenius Wilhelmsen goes ex-dividend on 26 August, with its next payment of US$0.61 per share due on 16 September. The trailing yield is about 6.5% on the current share price, backed by US$1.15 in payments over the past year. Payout ratios stand at 55% of profit and 82% of free cash flow, which the analysis judges as sustainable, supported by five-year earnings growth of 25% a year and eight-year average dividend growth of about 33% a year.", "kImp": "높은 배당수익률과 견조한 배당 이력은 강한 주주환원 정책을 보여주지만, Q2·상반기 이익이 전년 대비 둔화된 가운데 이익·현금흐름의 절반 이상을 배당으로 지급하는 구조는 향후 시황 악화 시 배당 성장 여력을 제약할 수 있다는 점에서 주목된다.", "eImp": "The high yield and consistent dividend record signal a strong shareholder-return policy, but with H1 2026 earnings softening year on year and more than half of profit and cash flow paid out, the payout leaves limited room for dividend growth and raises resilience questions if shipping markets weaken.", "url": "https://simplywall.st/stocks/no/transportation/ob-wawi/wallenius-wilhelmsen-shares/news/income-investors-should-know-that-wallenius-wilhelmsen-asa-o"}, {"code": "WW", "title": "발레니우스 빌헬름센(Wallenius Wilhelmsen), 8월 26일 주당 0.61달러 배당락 거래 개시", "eTitle": "Wallenius Wilhelmsen ASA: Trading ex. dividend of USD 0.61 today", "src": "Oslo Bors (walleniuswilhelmsen.com)", "date": "2026-08-26", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)은 8월 26일부터 주당 0.61달러 배당락 상태로 거래를 시작한다고 오슬로증권거래소(Oslo Bors)에 공시했다. 이는 상반기(H1 2026) 배당으로, 순이익의 50%에 해당하는 보통배당 0.37달러와 특별배당 0.24달러(총 약 1억 달러 규모)로 구성되며, 배당금은 9월 16일경 지급될 예정이다.", "eSum": "Wallenius Wilhelmsen notified the Oslo Bors that its shares trade ex-dividend of USD 0.61 per share from 26 August. The H1 2026 distribution combines an ordinary dividend of USD 0.37 (50% of net profit) and an extraordinary element of USD 0.24 per share (roughly USD 100 million in total), with cash payment scheduled on or about 16 September.", "kImp": "상반기 실적이 전년 대비 둔화됐음에도 특별배당을 포함한 대규모 현금환원을 단행한 것은, 견조한 계약 수주잔고와 재무 유연성에 대한 경영진의 자신감과 강한 주주환원 기조를 재확인한 조치로 해석된다.", "eImp": "Paying out a sizeable cash return, including an extraordinary dividend, despite weaker year-on-year H1 results reaffirms management's confidence in its contract backlog and balance-sheet flexibility, underscoring a firmly shareholder-friendly capital policy.", "url": "https://newsweb.oslobors.no/message/680789"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "미쓰이 E&S(Mitsui E&S), 암모니아 엔진·연료공급시스템 상용화 단계 진입", "eTitle": "Mitsui E&S Moves Ammonia Engines and Fuel Systems to Commercial Stage", "src": "Ship & Bunker", "date": "2026-08-21", "kSum": "일본 미쓰이 E&S(Mitsui E&S)가 암모니아 이중연료 엔진과 암모니아 연료공급시스템의 상용화를 완료해 실선용으로 공급할 수 있게 됐다고 밝혔다. 미쓰이-에버런스(Mitsui-Everllence) 엔진과 연료시스템의 육상 통합시험이 2026년 2월 ClassNK 입회 하에 완료됐으며, NOx 인증으로 IMO 기준 충족이 확인됐다. 회사는 에버런스·WinGD 라이선스 엔진을 모두 지원하도록 시험설비를 확충하고 양산체제를 구축할 계획이다.", "eSum": "Japan's Mitsui E&S said it has completed commercialization of its ammonia dual-fuel engines and ammonia fuel supply systems, enabling supply for actual vessels. Land-based integrated testing of the Mitsui-Everllence engine and fuel system finished in February 2026, witnessed by ClassNK, with NOx certification confirming IMO compliance. The firm is expanding test facilities to support both Everllence- and WinGD-licensed engines and plans a mass-production system.", "kImp": "암모니아 추진 기술이 시연 단계를 넘어 주요 엔진 제작사로부터 실제 발주 가능한 상용 제품으로 전환됐음을 보여주는 것으로, 무탄소 신조선 확산의 핵심 동력이다.", "eImp": "Signals ammonia propulsion moving from demonstration to a commercially orderable product from a major engine builder, a key enabler for zero-carbon newbuilds.", "url": "https://shipandbunker.com/news/apac/628157-mitsui-es-moves-ammonia-engines-and-fuel-systems-to-commercial-stage"}, {"code": "EE", "title": "수노일(Sunoil), B100 전환 내륙바지선 긍정적 운항 결과 발표", "eTitle": "Sunoil Says B100-Fuelled Inland Barge Shows Positive Results After May Conversion", "src": "Ship & Bunker", "date": "2026-08-24", "kSum": "네덜란드의 수노일(Sunoil)은 5월 100% 바이오디젤(B100)로 전환한 내륙바지선 비르요 II(Birjo II)가 엔진 교체 없이도 수개월째 양호하게 운항 중이라고 밝혔다. 필터 시스템 모니터링 결과가 기대 이상이며, 이번 전환으로 CO2 배출을 최대 약 90%까지 줄일 수 있다고 설명했다. 수노일은 이 프로젝트가 유럽 전역 추가 내륙바지선의 B100 전환을 뒷받침할 수 있다고 전망했다.", "eSum": "Netherlands-based Sunoil reports the inland barge Birjo II is running well several months after a May conversion to 100% biodiesel (B100) without an engine replacement. Filter-system monitoring shows better-than-expected results, and the switch could cut CO2 emissions by up to about 90%. Sunoil says the project could support converting additional inland barges to B100 across Europe.", "kImp": "자본 부담이 큰 엔진 교체 없이 기존 선박에 적용 가능한 저비용 드롭인 바이오연료 탈탄소 경로를 실증한 사례다.", "eImp": "Demonstrates a low-cost, drop-in biofuel decarbonization path for existing vessels without capital-heavy engine swaps.", "url": "https://shipandbunker.com/news/emea/447360-sunoil-says-b100-fuelled-inland-barge-shows-positive-results-after-may-conversion"}, {"code": "EE", "title": "DNV, 2030년 이후 저탄소 선박연료 시장 급성장 전망", "eTitle": "DNV Sees Rapid Growth in Low-GHG Marine Fuel Market After 2030", "src": "Ship & Bunker", "date": "2026-08-27", "kSum": "DNV의 제10차 '2050 해운 전망(Maritime Forecast to 2050)'은 저탄소 선박연료 수요가 2030년 4~22 Mtoe에서 2050년 33~185 Mtoe로 늘어날 것으로 전망했으며, 이는 IMO 넷제로 프레임워크 채택 여부에 좌우된다. 바이오연료(바이오메탄, 사탕수수 에탄올, 폐유 바이오디젤)가 약 180~300달러/tCO2eq의 저감비용으로 초기 전환을 주도하고, e-암모니아 등 e-연료는 2050년 380달러/tCO2eq 수준으로 비용이 하락하며 확대될 것으로 봤다. DNV는 바이오연료 수요가 공급을 초과할 수 있고 단일 글로벌 저탄소 연료가격은 형성되지 않을 것이라고 경고했다.", "eSum": "DNV's 10th Maritime Forecast to 2050 projects low-GHG marine fuel demand of 4-22 Mtoe by 2030, rising to 33-185 Mtoe by 2050 depending on whether the IMO Net-Zero Framework is adopted. Biofuels are expected to lead the early transition at roughly $180-300/tCO2eq abatement cost, with e-fuels like e-ammonia gaining ground as costs fall toward $380/tCO2eq by 2050. DNV warns biofuel demand may outpace supply and that no single global low-GHG fuel price will emerge.", "kImp": "해운 에너지 전환의 규모와 연료믹스 불확실성을 규정하며, 규제가 대체연료 수요를 좌우하는 결정 변수임을 보여준다.", "eImp": "Frames the scale and fuel-mix uncertainty of shipping's energy transition, with regulation as the decisive variable for alternative-fuel demand.", "url": "https://shipandbunker.com/news/world/827272-dnv-sees-rapid-growth-in-low-ghg-marine-fuel-market-after-2030"}, {"code": "EE", "title": "UCL, IMO 핵심 협상 앞두고 해운 온실가스 배출 탐색기(GHG Emissions Explorer) 공개", "eTitle": "UCL Debuts Shipping GHG Emissions Explorer Ahead of Crunch IMO Talks", "src": "Splash247", "date": "2026-08-27", "kSum": "유니버시티칼리지런던(UCL)이 4만3,000척 이상 선박의 120만 항차 데이터를 기반으로 한 대화형 '해운 온실가스 배출 탐색기'를 공개했다. 국제해운의 CO2 환산 배출 약 5억7,500만 톤을 개별 국가에 귀속시키고 항내·항해 중 배출을 구분한다. 초기 분석 결과 국제해운 배출의 약 10%가 항내에서 발생해 육상전력·전기화의 필요성을 뒷받침한다. UCL은 넷제로 프레임워크 협상 재개를 앞두고 IMO 대표단의 근거 기반을 강화하기 위한 도구라고 밝혔다.", "eSum": "University College London launched an interactive Shipping GHG Emissions Explorer, built from 1.2m voyages by 43,000+ vessels, attributing an estimated 575m tonnes of CO2-equivalent from international shipping to individual countries and splitting in-port versus in-voyage emissions. An early finding is that about 10% of international shipping emissions occur in port, underscoring the case for shore power and electrification. UCL says the tool is meant to strengthen the evidence base for IMO delegations as Net-Zero Framework negotiations resume.", "kImp": "결정적인 넷제로 프레임워크 협상을 앞둔 IMO 회원국들에게 국가별 배출에 관한 더 정밀한 데이터를 제공한다.", "eImp": "Gives IMO member states harder national-level emissions data as they head into decisive Net-Zero Framework talks.", "url": "https://splash247.com/ucl-debuts-shipping-ghg-emissions-explorer-ahead-of-crunch-imo-talks/"}, {"code": "EE", "title": "울트라막스 벌커에 강성 윙세일(rigid wingsail) 개조 완료", "eTitle": "Rigid Wingsail Retrofit Completed on Ultramax Bulker", "src": "Splash247", "date": "2026-08-27", "kSum": "선주 토픽(Topic)이 6만155DWT급 울트라막스 벌커 마리아 토픽(Maria Topic)에 일본 쓰네이시조선에서 오션윙스(OceanWings) 강성·틸팅형 윙세일을 장착한 뒤 운항에 복귀시켰으며, 이는 울트라막스 벌커에 대한 이 기술의 첫 적용이다. 이번 개조는 6개국 13개 파트너가 참여하는 EU 지원 WHISPER 프로젝트의 일환으로 모듈형 풍력추진을 시험하며, 솔비안(Solbian) 태양광 패널도 함께 설치됐다. 첫 운항 성능 데이터는 다음 달 SMM 함부르크에서 공개될 예정이다.", "eSum": "Owner Topic has returned its 60,155 dwt ultramax Maria Topic to service after fitting an OceanWings rigid, tiltable wingsail at Tsuneishi Shipbuilding in Japan, the first application on an ultramax bulker. The retrofit is part of the EU-backed WHISPER project (13 partners, six countries) testing modular wind propulsion, with Solbian solar panels also installed. First operational performance data will be released at SMM Hamburg next month.", "kImp": "강성 윙세일 풍력추진 기술을 대형 벌크선 부문으로 확장한 구체적 개조 이정표다.", "eImp": "A concrete wind-propulsion retrofit milestone extending rigid wingsail technology into the large dry-bulk segment.", "url": "https://splash247.com/rigid-wingsail-retrofit-completed-on-ultramax-bulker/"}, {"code": "EE", "title": "중국 광석운반선, 세계 최초 선박 태양광 선급 인증 취득 주장", "eTitle": "Chinese Ore Carrier Claims World-First Solar Class Certificate", "src": "Splash247", "date": "2026-08-26", "kSum": "산둥해운(Shandong Shipping)의 25만DWT급 광석운반선 산둥허셰(Shandong Hexie)가 중국선급(CCS)이 세계 최초라고 밝힌 선박 태양광(PV) 시스템 선급 인증을 취득했다. 3상 마이크로 인버전 기술을 적용해 연간 약 33톤의 연료와 102.8톤의 CO2를 절감할 것으로 예상된다. 이 태양광 어레이는 연료 소비를 약 25% 줄이는 광범위한 효율화 프로그램의 일부로, 인증된 고전압 육상전력 시스템도 함께 갖췄다.", "eSum": "Shandong Shipping's 250,000 dwt ore carrier Shandong Hexie received what China Classification Society calls the world's first class certificate for a shipboard solar PV system, using three-phase micro-inversion technology expected to cut about 33 tonnes of annual fuel use and 102.8 tonnes of CO2. The solar array is part of a wider efficiency programme cutting fuel consumption by about 25%, alongside a certified high-voltage shore-power system.", "kImp": "초대형 벌커에 대한 세계 최초의 선급 인증 선박 태양광 설치로, 중국 선대에서 성숙해지는 친환경 선박 에너지효율 기술을 보여준다.", "eImp": "A first-of-its-kind classed onboard solar installation on a very large bulker, signalling maturing green-ship energy-efficiency technology in China's fleet.", "url": "https://splash247.com/chinese-ore-carrier-claims-world-first-solar-class-certificate/"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "외텐쇼 레데리(Østensjø Rederi), 디파이(Dipai) 디지털 선대 플랫폼 확대 적용", "eTitle": "Østensjø Rederi to expand use of Dipai digital fleet platform", "src": "Smart Maritime Network", "date": "2026-08-27", "kSum": "노르웨이 선주 외텐쇼 레데리가 디파이(Dipai)의 디지털 선대 플랫폼을 오프쇼어 선대와 일부 예인선으로 확대 적용하기로 했다. 2026년 4월 첫 선박 도입 이후 협력을 연장하는 것으로, 이 플랫폼은 엔진·스러스터·선체·하중·항법·기상 데이터를 통합해 AI와 분석 모델로 운항 모드 및 연료 보고를 자동화하고 연료 소비, 배출, 정비에 대한 의사결정을 지원한다.", "eSum": "Norwegian owner Østensjø Rederi will expand Dipai's Digital Fleet Platform across its offshore fleet and selected tugs after onboarding its first vessel in April 2026. The platform integrates data from engines, thrusters, hull, load, navigation and weather systems, using vessel sensor data, AI and analytics to automate operational-mode and fuel reporting and provide decision support for fuel, emissions and maintenance.", "kImp": "센서 데이터 기반 통합 플랫폼이 파일럿을 넘어 선대 전반으로 확산되는 사례로, 데이터 중심 운항과 에너지 효율 개선이 오프쇼어 부문에서 실질적 도입 단계에 진입했음을 보여준다.", "eImp": "Marks a move from pilot to fleet-wide rollout of a sensor-driven integrated platform, showing data-driven operations and energy-efficiency gains reaching practical adoption in the offshore segment.", "url": "https://smartmaritimenetwork.com/2026/08/27/ostensjo-rederi-to-expand-use-of-dipai-digital-fleet-platform/"}, {"code": "DIG", "title": "안쉬츠(Anschütz), 오토노믹스(AUTONOMICS)에 충돌회피 시스템 추가", "eTitle": "Anschütz adds collision avoidance system to AUTONOMICS", "src": "Smart Maritime Network", "date": "2026-08-27", "kSum": "안쉬츠가 자사 오토노믹스(AUTONOMICS) 플랫폼용 항법 의사결정 지원 시스템 '오토노믹스 CGA'를 개발했다. 레이더, AIS, 전자해도, AI 기반 EO/IR 센서 데이터를 결합해 실시간 항행 상황도를 생성하고, 충돌·좌초 위험을 COLREG 기준으로 분석해 안전한 조종 궤적을 지속 계산·갱신한다. 침로 변경 조작은 안쉬츠 오토파일럿으로 직접 전송해 실행할 수 있다.", "eSum": "Anschütz has developed AUTONOMICS CGA, a navigation decision-support system that combines radar, AIS, electronic charts and AI-supported EO/IR sensors to build a real-time picture, assess collision and grounding risks against COLREG requirements, and continuously generate collision-avoidance trajectories. Heading-only manoeuvres can be transferred directly to an Anschütz autopilot. The system will soon enter validation with selected customers.", "kImp": "AI 센서 탐지와 COLREG 기반 자동 조종 권고를 결합해 자율운항 브리지 기술이 실제 검증 단계로 나아가는 흐름을 보여준다. 항해사의 수작업 분석 부담 경감이 핵심이다.", "eImp": "Combines AI sensor detection with COLREG-based manoeuvring guidance and autopilot execution, advancing autonomous bridge technology toward real validation while reducing navigators' manual workload.", "url": "https://smartmaritimenetwork.com/2026/08/27/anschutz-adds-collision-avoidance-system-to-autonomics/"}, {"code": "DIG", "title": "일본선급(ClassNK), 선주·선박관리사용 출처기반 AI 검사 도구 '서베이 컴퍼스' 출시", "eTitle": "ClassNK puts source-backed AI into survey work for shipowners and ship managers", "src": "The Digital Ship", "date": "2026-08-26", "kSum": "일본선급(ClassNK)이 검사 관련 업무를 지원하는 AI 어시스턴트 '서베이 컴퍼스(Survey Compass)'를 출시했다. ClassNK 커스터머 허브를 통해 자연어로 질문하면 선급 검사 문서를 검색해 간결한 답변과 함께 출처 문서 링크를 제공한다. 검색 기반(retrieval) 방식으로 원문에서 답을 도출해 AI의 부정확성 위험을 줄였으며, 초기 버전은 강선 검사·건조 규칙 B편 등을 다룬다.", "eSum": "ClassNK has launched Survey Compass, an AI assistant that lets shipowners and managers ask survey questions in natural language and returns concise answers with links to source documents via the ClassNK Customer Hub. Using a retrieval-based method drawing on source material to reduce inaccuracy, the first release covers Part B of the Rules for Survey and Construction of Steel Ships and related guidance, with plans to add conventions and flag-State requirements.", "kImp": "출처 추적이 가능한 검색기반 AI로 검사 준비 시간을 단축하면서 최종 판단은 사람에게 남기는 실무형 AI 적용 사례다. 선급의 인서비스 디지털 서비스 플랫폼 구상의 첫걸음이다.", "eImp": "A practical, source-traceable retrieval AI that cuts survey preparation time while keeping final judgement with people, marking ClassNK's first step toward a digital service platform for ships in service.", "url": "https://thedigitalship.com/news/maritime-software/classnk-puts-source-backed-ai-into-survey-work-for-shipowners-and-ship-managers/"}, {"code": "DIG", "title": "SK텔링크·인마샛(Inmarsat), 한국 선대 대상 넥서스웨이브(NexusWave) 확대 추진", "eTitle": "SK telink and Inmarsat target wider NexusWave use across South Korean fleets", "src": "The Digital Ship", "date": "2026-08-26", "kSum": "SK텔링크와 인마샛 마리타임(Inmarsat Maritime)이 자동차운반선·컨테이너선·VLCC 등 한국 선사 선대에 넥서스웨이브(NexusWave) 연결성을 확대 도입하기 위한 협약을 체결했다. HMM, 시노코(SINOKOR) 등이 대상으로 거론됐다. 넥서스웨이브는 복수 네트워크를 관리형 서비스로 결합해 클라우드 애플리케이션, 사이버보안, 데이터 기반 선대 운영을 지원하며, 향후 바이아샛-3(Viasat-3) 통합으로 역내 용량이 확대될 전망이다.", "eSum": "SK telink and Inmarsat Maritime signed an agreement to bring NexusWave connectivity to more South Korean owners across car carriers, container ships and VLCCs, with HMM and SINOKOR among those identified. NexusWave combines multiple network underlays in a managed service to support cloud applications, cybersecurity and data-driven operations, with planned Viasat-3 integration set to add regional capacity on busy Asian routes.", "kImp": "선박 시스템의 육상 연결 의존이 커지면서 회복력 있는 다중망 연결이 사이버보안·성능관리의 기반으로 부상하고 있음을 보여준다. 한국 대형 선사의 디지털 운영 전환을 뒷받침하는 인프라 협력이다.", "eImp": "As vessel systems increasingly depend on shore connectivity, resilient multi-network links are becoming the foundation for cybersecurity and performance management, underpinning South Korean owners' shift to digital, data-driven operations.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/sk-telink-and-inmarsat-target-wider-nexuswave-use-across-south-korean-fleets/"}, {"code": "DIG", "title": "왓슨 팔리 앤 윌리엄스(WFW), \"해운 디지털화로 사이버 회복력이 이사회 의제로\"", "eTitle": "Watson Farley & Williams says maritime digitalisation is putting cyber resilience at board level", "src": "The Digital Ship", "date": "2026-08-27", "kSum": "법무법인 왓슨 팔리 앤 윌리엄스(WFW)가 선대 시스템이 클라우드·통신망·외부 공급자와 연결되면서 사이버보안이 운영·거버넌스 문제로 진화하고 있다고 분석했다. EU의 NIS2 지침과 CER(핵심주체 회복력) 지침이 사이버 위험관리, 사고보고, 공급망 보안, 물리적 연속성·복구 책임을 강화하고 있으며, 사이버보안과 회복력이 기술팀만의 사안이 아닌 이사회 책임으로 부상하고 있다고 지적했다.", "eSum": "Law firm Watson Farley & Williams says digitalisation has changed ship management's risk profile as once-isolated systems connect to wider IT environments and third parties. The EU NIS2 Directive and Critical Entities Resilience (CER) Directive push cybersecurity risk management, incident reporting, supply-chain security and continuity/recovery duties, making cyber resilience a board-level responsibility rather than a technical-team matter, with third-party suppliers firmly in the risk picture.", "kImp": "규제가 사이버 회복력을 이사회 책임으로 끌어올리고 공급망까지 포괄하면서, 해운기업이 예방을 넘어 필수기능 유지·복구 체계와 공급자 거버넌스를 갖춰야 하는 시대로 진입했음을 보여준다.", "eImp": "Regulation is elevating cyber resilience to board responsibility and extending it across supply chains, pushing shipping firms beyond prevention toward continuity, recovery and supplier-governance frameworks.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/watson-farley-williams-says-maritime-digitalisation-is-putting-cyber-resilience-at-board-level/"}, {"code": "DIG", "title": "쿤텍(COONTEC), IACS E26 대비 7종 실사이버공격 실증 시연", "eTitle": "COONTEC tests seven live cyberattacks as shipowners prepare for IACS E26", "src": "The Digital Ship", "date": "2026-08-21", "kSum": "쿤텍(COONTEC)이 판교 테스트베드에서 8월 5일과 12일 가상 선박 두 척을 구축해 7종의 실시간 사이버공격 시나리오를 시연했다. 한국 선사·선박관리사·조선소·기자재사·한국선급(KR) 관계자가 참관했으며, 자사 테라그리드 마리타임(TGM) 플랫폼이 NDR·EDR로 공격을 탐지·자동 격리했다. 공격 기록을 IACS UR E26 준수 문서와 연계해 클래스 제출용 보고서를 생성하는 KR-CRP 플랫폼도 소개했다.", "eSum": "COONTEC ran seven live cyberattack scenarios on two virtual vessels at its Pangyo testbed on 5 and 12 August, attended by Korean owners, managers, shipyards, equipment makers and Korean Register. Its TeraGRID Maritime platform detected and isolated attacks via NDR and EDR, while its KR-CRP platform aggregates detection records against IACS UR E26 requirements for class submission—cutting one shipyard's asset-list preparation from three months to two weeks.", "kImp": "2024년 7월 이후 건조계약 선박이 사이버 연례검사를 받게 되면서, 사이버보안 기록이 선박 운영 이력의 일부가 되는 현실을 보여준다. 탐지뿐 아니라 유지 증빙이 관리 부담의 핵심이 된다.", "eImp": "With vessels contracted from July 2024 facing cyber annual surveys under IACS UR E26, cybersecurity records are becoming part of a vessel's operational history—shifting the management burden from detection alone to provable maintenance of cyber condition.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/coontec-tests-seven-live-cyberattacks-as-shipowners-prepare-for-iacs-e26/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "MSC와 요툰, 로봇 선체 청소로 협력", "eTitle": "MSC and Jotun join forces over robotic hull cleaning", "src": "Safety4Sea", "date": "2026-08-26", "kSum": "MSC와 도료업체 요툰이 컨테이너선 MSC Daniela에 요툰의 'Hull Skating Solutions(HSS)'를 설치했다. HSS는 선체에 상주하는 로봇이 오손(fouling)이 형성되기 전에 선체를 상시 청소해 선체 마찰 저항을 낮추고 연료 소비와 배출을 줄이는 사전예방형 방오 솔루션이다. 정기적 선체 관리로 선박 성능을 유지하는 것이 목표다.", "eSum": "", "kImp": "선체 오손 관리는 연료비와 CII 성능에 직접 영향을 미치므로, 상시 로봇 청소 방식은 기술감독이 입거 주기 사이에도 선체 성능을 유지·관리할 수 있는 실질적 대안이 된다.", "eImp": "", "url": "https://safety4sea.com/msc-and-jotun-join-forces-over-robotic-hull-cleaning/"}, {"code": "TECH", "title": "DNV \"불확실한 규제 환경에서 효율이 핵심\"", "eTitle": "Efficiency critical in volatile regulatory climate says DNV", "src": "Seatrade Maritime", "date": "2026-08-27", "kSum": "DNV는 제10차 에너지 전환 전망(Maritime Forecast to 2050)에서 LNG를 대체·가교 연료로 내세우던 기존 입장에서 벗어나 선박 에너지 효율의 중요성을 강조했다. 올해 보고서의 핵심 주제는 'Net Zero Framework(NZF)' 등 규제 불확실성 속에서의 의사결정으로, 대체연료뿐 아니라 육상전력·선상 탄소포집 등 다양한 기술 대안을 폭넓게 다뤘다. 다만 에너지효율 조치는 절감 효과 검증이 어려워 투자 판단에 신뢰할 수 있는 검증 방법이 필요하다고 지적했다.", "eSum": "", "kImp": "규제 향방이 불확실한 상황에서 기술감독은 특정 연료에 올인하기보다 검증 가능한 에너지효율 조치와 연료 유연성 확보에 우선순위를 둘 필요가 있다.", "eImp": "", "url": "https://www.seatrade-maritime.com/regulations/efficiency-critical-in-volatile-regulatory-climate-says-dnv"}, {"code": "TECH", "title": "ESVAGT NJORD호, 파랑 예측 시스템 도입", "eTitle": "ESVAGT NJORD to deploy wave prediction system", "src": "Smart Maritime Network", "date": "2026-08-27", "kSum": "해상풍력 지원선(SOV) ESVAGT NJORD호가 Dudgeon 풍력단지 작업 지원을 위해 NextOcean의 'WavePredictor' 동요 예측 시스템을 도입한다. 모션 레이더와 소프트웨어는 이달 중 설치될 예정으로, 향후 수 분간의 선박 동요를 실시간 예측해 승무원의 go/no-go 판단과 인원 이송을 지원한다.", "eSum": "", "kImp": "실시간 동요 예측은 거친 해상에서의 인원 이송 안전성과 작업 가능일수를 동시에 높여, 오프쇼어 지원선 운영의 안전·가동률 관리에 기여한다.", "eImp": "", "url": "https://smartmaritimenetwork.com/2026/08/27/esvagt-njord-to-deploy-wave-prediction-system/"}, {"code": "TECH", "title": "SMM 함부르크 2026: 해양기술·혁신의 미래", "eTitle": "SMM Hamburg 2026: The future of maritime technology and innovation", "src": "Seatrade Maritime", "date": "2026-08-25", "kSum": "세계 최대 해양 무역박람회 SMM이 2026년 함부르크에서 열리는 것을 앞두고, 탈탄소화·디지털화·대체연료 등 해양기술과 혁신의 향방을 조망하는 미리보기다. 선박 기술 관리와 관련된 최신 기술 트렌드와 산업 동향이 논의 주제로 다뤄진다.", "eSum": "", "kImp": "기술감독에게 SMM은 대체연료·추진·디지털 기술 등 신기술 도입 방향을 파악하고 벤더 동향을 점검하는 주요 지표가 된다.", "eImp": "", "url": "https://www.seatrade-maritime.com/event-news/smm-hamburg-2026-the-future-of-maritime-technology-and-innovation"}, {"code": "TECH", "title": "ADNOC L&S, 장난조선소에 LNG선 2척 추가 발주", "eTitle": "ADNOC L&S adds LNG carrier pair at Jiangnan Shipyard", "src": "Seatrade Maritime", "date": "2026-08-27", "kSum": "ADNOC 물류·서비스(L&S)가 중국 장난조선소에 175,000㎥급 LNG선 2척 옵션을 행사해 7월에 체결한 '4+2' 계약의 6척을 모두 확정했으며, 전량 2029년 인도 예정이다. 장난조선소가 자체 설계한 이 최신 세대 '그린·인텔리전트' LNG선은 성능을 개선하고 온실가스 배출을 줄였으며, 자체 개발한 JNIS 스마트십 플랫폼을 탑재해 전 세계 160여 개 LNG 터미널·FLNG 설비와 호환된다.", "eSum": "", "kImp": "스마트십 플랫폼과 저배출 설계를 적용한 신조 LNG선 사양은 기술감독이 신조 감독과 향후 선대 기술표준을 검토할 때 참고할 최신 사례가 된다.", "eImp": "", "url": "https://www.seatrade-maritime.com/tankers/adnoc-l-s-adds-lng-carrier-pair-at-jiangnan-shipyard"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "선원은 소모품이 아니다", "eTitle": "Seafarers are not expendable", "src": "Splash247", "date": "2026-08-24", "kSum": "호르무즈 해협에서 미노안 디그니티호 기관장이 공격으로 사망한 사건을 계기로, 분쟁 해역 선원 보호를 위한 강제력 있는 조치가 필요하다는 기고문이다. 필자는 선원이 임금·경력 손실 없이 분쟁 지역 통항을 거부할 권리와 적절한 보상·보험·대피 보장을 요구했다. 규탄 성명만으로는 부족하며 업계·노조·화주가 한목소리로 공동 대응해야 한다고 강조한다.", "eSum": "", "kImp": "분쟁 해역에서 민간 선원을 보호하기 위한 산업계 공동의 강제적 조치 필요성을 제기하는 선주·경영진 대상 논평이다.", "eImp": "", "url": "https://splash247.com/seafarers-are-not-expendable/"}, {"code": "HR", "title": "헤이그 비선원업무조항 항소심에 ETUC 참가로 노조 연대 강화", "eTitle": "Union unity strengthened in Hague Non-Seafarers' Work Clause appeal as ETUC joins proceedings", "src": "ITF Global", "date": "2026-08-27", "kSum": "헤이그 항소법원이 유럽노동조합총연맹(ETUC)의 '비선원업무조항(NSWC)' 항소심 참가를 허가했다. NSWC는 항만에 자격 있는 항만노동자가 있을 때 선원이 래싱 등 화물 하역작업을 하지 못하도록 하는 ITF 협약의 안전 조항이다. ITF는 이번 결정이 유럽 전역의 단체교섭권과 집단적 권리 보호에 중요한 의미를 갖는다고 평가했다.", "eSum": "", "kImp": "선원의 과로·안전과 직결된 화물작업 규정을 둘러싼 법적 다툼으로, 단체교섭권 보호 관점에서 선원 노동권 판례에 영향을 미친다.", "eImp": "", "url": "https://www.itfglobal.org/en/news/union-unity-strengthened-in-hague-non-seafarers-work-clause-appeal-etuc-joins-proceedings"}, {"code": "HR", "title": "여성 생도의 영향은 본인 경력을 넘어선다", "eTitle": "Female cadets have an impact well beyond their own career", "src": "Seatrade Maritime", "date": "2026-08-21", "kSum": "MOL이 필리핀 막사이사이와 운영하는 해양아카데미(MMMA)가 올해 역대 최다인 여성 생도 31명을 포함해 208명을 받아들였다. MOL 아시아·오세아니아 대표 사쿠라 쿠마는 여성 생도가 다음 세대의 롤모델이 되며 해양 전문가의 이미지를 바꿀 것이라고 말했다. 그는 성별·국적·배경과 무관하게 인재풀을 확대해야 한다고 강조했다.", "eSum": "", "kImp": "선원 인력난 속에서 여성 채용 확대와 다양성 제고가 미래 인력 확보와 산업 이미지 개선의 핵심임을 보여준다.", "eImp": "", "url": "https://www.seatrade-maritime.com/crewing/female-cadets-have-an-impact-well-beyond-their-own-career"}, {"code": "HR", "title": "선원 정신건강, 인식에서 실천으로: 해상 웰빙의 다음 단계", "eTitle": "Mental wellbeing at sea: Moving from awareness to action", "src": "Safety4Sea", "date": "2026-08-27", "kSum": "NorthStandard 아시아태평양 손실예방 책임자 이브 반덴보른(Capt. Yves Vandenborn)이 기고한 글로, 2만여 명 선원을 대상으로 한 조사에서 정신건강이 선원 웰니스 중 가장 취약한 영역으로 확인됐다고 전한다. 지원 접근성 부족과 실질적 대처법 정보 부족이 주요 장벽으로 꼽혔으며, ILO 자료 기준 2023년 선원 사망의 6.5%가 자살이었다. NorthStandard는 인식·역량·지원·환경·리더십 5개 축의 'My Mind Matters at Sea' 프레임워크와 동료지원 훈련 프로그램 'Sea Mate'를 제시했다.", "eSum": "", "kImp": "정신건강을 선박 안전·운항성과·선원 유지율과 직결된 운영 리스크로 다루고, 단순 인식 단계를 넘어 안전관리체계(SMS)에 통합되는 실질적 도구가 필요함을 강조한다.", "eImp": "", "url": "https://safety4sea.com/mental-wellbeing-at-sea-moving-from-awareness-to-action/"}, {"code": "HR", "title": "AMSA '선원 복지는 해상 안전의 근간'", "eTitle": "AMSA: Seafarer welfare is fundamental to maritime safety", "src": "Safety4Sea", "date": "2026-08-25", "kSum": "호주해사안전청(AMSA) 신임 해사안전·환경준수 총괄이사 그렉 위더럴(Greg Witherall)이 인터뷰에서 선원 복지가 국제 해운이 직면한 가장 중요한 현안 중 하나라고 밝혔다. 그는 피로, 임금, 의료 접근성, 생활환경, 정신 웰빙은 안전과 분리된 문제가 아니라 곧 안전 문제라고 강조했다. 또 안전은 규제기관이 아니라 매일 판단을 내리는 선원이 만든다며 안전문화 정착과 인적요소 관리를 최우선 과제로 꼽았다.", "eSum": "", "kImp": "규제당국이 선원 복지 기준 위반에 대한 '무관용' 원칙을 재확인하고 복지와 안전을 하나로 보는 접근을 제시해, 선사·선박관리사의 준수 방향에 시사점을 준다.", "eImp": "", "url": "https://safety4sea.com/cm-amsa-seafarer-welfare-is-fundamental-to-maritime-safety/"}, {"code": "HR", "title": "West P&I '훈련이 선원 자신감·역량·안전문화의 열쇠'", "eTitle": "West Club: Training is key to building confidence, competence and a strong safety culture", "src": "Safety4Sea", "date": "2026-08-27", "kSum": "West P&I 손실예방 책임자 사이먼 호지킨슨(Capt. Simon Hodgkinson)이 SAFETY4SEA 인터뷰에서 여전히 사고의 상당수가 피로·부실한 선교자원관리 등 인적요소에서 비롯된다고 지적했다. 그는 늘어나는 행정부담·상업적 압박·소규모 승선인원이 피로와 주의분산을 키운다며, 디지털화·자동화·대체연료로 요구 역량이 바뀌는 만큼 훈련이 단순 규정준수를 넘어서야 한다고 강조했다. 아울러 상륙휴가 보장 등 실질적 복지 조치를 권고했다.", "eSum": "", "kImp": "복잡해지는 선박·기술 환경에서 지속적 교육훈련과 상륙휴가 같은 복지가 선원 유지와 안전문화 강화의 핵심임을 보여준다.", "eImp": "", "url": "https://safety4sea.com/cm-west-club-training-is-key-to-building-confidence-competence-and-a-strong-safety-culture/"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "호주해사안전청(AMSA), 개정판 GMDSS 핸드북 발간", "eTitle": "AMSA issues updated GMDSS Handbook", "src": "Safety4Sea", "date": "2026-08-24", "kSum": "호주해사안전청(AMSA)이 세계해상조난안전제도(GMDSS) 핸드북 개정판을 발간해 기존 판을 대체했다. 개정판은 호주 해역 책임구역에서 운항하는 선박을 위한 조난·안전 통신 운용 지침을 갱신했다. 선박의 조난통신 절차 및 장비 운용 관련 최신 기준을 반영한다.", "eSum": "", "kImp": "조난·안전 통신 운용 기준을 최신화한 자료로, 해당 해역 운항 선박의 GMDSS 절차 준수 및 비상대응 역량 유지에 참고가 된다.", "eImp": "", "url": "https://safety4sea.com/amsa-issues-updated-gmdss-handbook/"}, {"code": "HSEQ", "title": "밀폐구역 진입 안전과 리스크 관리 — 스팀십뮤추얼 리스크 경보 146", "eTitle": "Enclosed spaces: safety and risk management (Steamship Mutual Risk Alert 146)", "src": "Steamship Mutual", "date": "2026-08-25", "kSum": "밀폐구역 진입은 인식 제고와 규정 강화에도 불구하고 여전히 선원 사망사고의 주요 원인으로 반복되고 있다. 밸러스트 탱크·화물창·보이드 스페이스·체인 로커 등은 겉보기에 안전해 보여도 산소결핍·유독가스·가연성 대기가 존재할 수 있고, 동료를 구조하려다 2차 피해가 발생하는 사례가 잦다. 스팀십뮤추얼은 매 진입 시 위험성 평가, 대기 측정, 환기, 통신, 감독, 비상대응 절차를 예외 없이 이행할 것을 강조했다.", "eSum": "", "kImp": "익숙한 작업에서 오는 방심이 사고의 핵심 원인인 만큼, 밀폐구역 진입을 형식적 서류 절차가 아닌 실질적 안전관리로 다뤄야 함을 재확인한다.", "eImp": "", "url": "https://www.steamshipmutual.com/publications/articles/enclosed-spaces-safety-and-risk-management"}, {"code": "HSEQ", "title": "인도 해안경비대, 침몰 벌크선 구명정 발견… 실종 선원 22명 생존 희박", "eTitle": "Hope fades for 22 missing crew as Indian Coast Guard finds sunken bulker's lifeboat", "src": "Maritime Executive", "date": "2026-08-25", "kSum": "인도 해안경비대와 해군이 인근 해역에서 침몰한 것으로 추정되는 벌크선의 실종 선원 22명에 대한 수색을 강화했다. 구명정이 발견됐으나 생존자는 확인되지 않아 구조 희망이 옅어지고 있다.", "eSum": "", "kImp": "대형 벌크선의 급작스러운 침몰과 다수 인명 실종 사고는 악천후 대응, 화물·복원성 관리, 비상탈출 대비의 중요성을 다시 부각한다.", "eImp": "", "url": "https://maritime-executive.com/article/hope-fades-for-survivors-as-indian-coast-guard-finds-lost-bulker-s-lifeboat"}, {"code": "HSEQ", "title": "갈라파고스 인근 참치 선망어선 화재… 선원 27명 전원 구조", "eTitle": "Good Samaritans rescue 27 from burning tuna seiner off Galapagos", "src": "Maritime Executive", "date": "2026-08-23", "kSum": "갈라파고스 인근 해역에서 화재가 발생한 참치 선망어선에서 선원 27명이 인근 선박과 미국 해안경비대의 지원으로 전원 구조됐다. 지난주 발생한 사고로 대규모 인명 피해는 면했다.", "eSum": "", "kImp": "어선 화재 시 신속한 조난 통보와 인근 선박·해경의 공조가 대규모 인명 손실을 막는 데 결정적임을 보여준다.", "eImp": "", "url": "https://maritime-executive.com/article/good-samaritans-rescue-27-from-burning-tuna-seiner-off-galapagos"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "해운 상장기업 브랜드 8월 빅데이터 분석…1위 HMM, 2위 팬오션, 3위 흥아해운", "eTitle": "August Shipping Brand Reputation Rankings: HMM 1st, Pan Ocean 2nd, Heung-A 3rd", "src": "쉬핑뉴스넷", "date": "2026-08-28", "kSum": "한국기업평판연구소의 2026년 8월 해운 상장기업 브랜드평판 분석에서 HMM이 브랜드평판지수 630만으로 1위를 지켰다. 2위는 팬오션(219만, 전월비 41.4%↑), 3위 흥아해운(142만), 4위 대한해운(94만), 5위 KSS해운, 6위 태웅로직스 순이었다. 7월28일~8월28일 빅데이터 1155만건을 분석한 결과로 전월 대비 20.18% 증가했다.", "eSum": "", "kImp": "국적 상장 해운사 브랜드 순위는 투자자·화주의 인식을 보여주는 지표다.", "eImp": "", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71790"}, {"code": "KR", "title": "친환경선박 확산으로 '녹색해운항로' 시대를 향해", "eTitle": "Korea Advances Toward 'Green Shipping Corridor' Era with Eco-Ships", "src": "쉬핑뉴스넷", "date": "2026-08-27", "kSum": "해양수산부는 세계 최초로 제정한 '녹색해운항로 구축 지원 특별법'의 시행령·시행규칙 제정안을 마련해 9월2일부터 10월13일까지 입법예고한다고 밝혔다. 내년 4월1일 시행을 앞두고 녹색선박 연료, 친환경 항만요건, 항로 지정·고시 기준 등을 규정했다. 아울러 해수부·산업부는 '제2차 친환경선박 개발·보급 기본계획(2026~2035)'을 공동 추진해 2035년까지 총 889척의 민간·공공선박 전환을 지원한다.", "eSum": "", "kImp": "해운 탈탄소 규제·지원체계 정비는 국적선사와 조선소의 친환경 전환 부담과 수주 기회를 좌우한다.", "eImp": "", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71778"}, {"code": "KR", "title": "현대글로비스, 항공 포워딩 통해 K-컬처 수출 돕는다", "eTitle": "Hyundai Glovis Supports K-Culture Exports via Air Freight Forwarding", "src": "쉬핑뉴스넷", "date": "2026-08-27", "kSum": "현대글로비스가 에이피알 화장품과 SM엔터테인먼트 음반을 미국·유럽으로 항공운송하며 항공포워딩 사업을 확대하고 있다. 포워더로서 포장·통관·선적·도착 전 과정을 관리하고, 미술품 등 고부가 소비재로 영역을 넓혀 비계열 고객 기반을 확대 중이다. 상반기에만 화장품·음반 물량 수백 톤 계약을 체결했으며, 인천공항물류센터와 에어제타 출자를 기반으로 육해공 종합물류체계를 강화한다.", "eSum": "", "kImp": "현대글로비스의 비계열 항공물류 확장은 사업 다각화와 수익구조 변화를 보여준다.", "eImp": "", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71770"}, {"code": "KR", "title": "여수광양항만공사, BS한양·광양그린에너지와 '친환경 에너지·스마트 물류허브' 구축 시동", "eTitle": "Yeosu-Gwangyang Port Authority Launches Green Energy & Smart Logistics Hub", "src": "쉬핑뉴스넷", "date": "2026-08-27", "kSum": "여수광양항만공사(YGPA)는 27일 BS한양·광양그린에너지와 '친환경 에너지 및 스마트 물류허브 구축' 업무협약을 체결했다. 10월 상업운전 예정인 광양 황금산단 220MW 바이오매스 발전소(총사업비 6804억원) 가동에 맞춰 광양항을 국내 최대 우드펠릿 수입·유통 거점 허브로 육성한다. 연간 약 4만5000TEU(월평균 3700TEU)의 신규 정기 물동량 창출이 기대된다.", "eSum": "", "kImp": "광양항의 신규 물동량 확보와 친환경 에너지 허브화는 항만 경쟁력과 배후단지 고부가화에 기여한다.", "eImp": "", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71779"}, {"code": "KR", "title": "부산항만공사, 신항 2-6단계 국산 트랜스퍼크레인 운송 착수", "eTitle": "Busan Port Authority Begins Delivery of Domestic Transfer Cranes for New Port Phase 2-6", "src": "코리아쉬핑가제트", "date": "2026-08-27", "kSum": "부산항만공사(BPA)가 부산항 신항 서컨테이너부두 2-6단계에 투입할 국산 자동화 하역장비의 현장 반입을 본격화했다. 2-6단계에 설치할 트랜스퍼크레인(T/C·야드크레인) 34기를 단계적으로 반입·설치한다.", "eSum": "", "kImp": "부산항 신항 자동화와 국산 하역장비 도입은 항만 경쟁력 강화 및 국산화 정책과 직결된다.", "eImp": "", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147926"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "이란·오만, 호르무즈해협 임시 통항 회랑 논의", "eTitle": "Iran and Oman Discussing Temporary Hormuz Corridor", "src": "Insurance Marine News", "date": "2026-08-27", "kSum": "이란과 오만 고위 외교관들이 호르무즈해협을 통과하는 임시 통항 회랑(코리도) 설치 방안을 논의했다. 중동 긴장 고조로 해협 통항 위험과 전쟁위험보험료가 급등한 가운데 통항 안전 확보를 위한 협의가 진행되고 있다.", "eSum": "", "kImp": "호르무즈 통항 안정화 여부는 선체·전쟁위험보험료와 탱커 운항에 직접적 영향을 미친다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/iran-and-oman-discussing-temporary-hormuz-corridor/"}, {"code": "INS", "title": "이탈리아 막시돌핀 조선소 화재로 요트 3척 전소", "eTitle": "Maxi Dolphin Shipyard Fire in Italy Destroys Three Yachts", "src": "Insurance Marine News", "date": "2026-08-27", "kSum": "이탈리아 북부 에르부스코 소재 막시돌핀(Maxi Dolphin) 조선소에서 대형 화재가 발생해 건조 중이던 15~27m급 요트 3척이 있던 생산동이 전소됐다.", "eSum": "", "kImp": "조선소 건조 중 화재는 선체·건조보험(builders' risk) 대형 손해로 이어지는 전형적 사례다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/maxi-dolphin-shipyard-fire-in-italy-sees-three-yachts-destroyed/"}, {"code": "INS", "title": "영국 카디프항서 벌크선 페더럴 웰런드 대형 화재", "eTitle": "Major Fire on Bulk Carrier Federal Welland in Cardiff", "src": "Insurance Marine News", "date": "2026-08-27", "kSum": "8월25일 영국 카디프 퀸알렉산드라 부두에 정박 중이던 벌크선 페더럴 웰런드(Federal Welland, IMO 9205926)에서 대형 화재가 발생해 다량의 연기가 발생했다.", "eSum": "", "kImp": "정박 중 선박 화재는 선체보험 및 항만·제3자 배상 리스크를 동반한다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/major-fire-on-bulk-carrier-in-cardiff/"}, {"code": "INS", "title": "다뉴브강 병목으로 우크라이나 곡물 수출 지연", "eTitle": "Queue Builds off Danube as Bottlenecks Slow Ukraine Grain Exports", "src": "Insurance Marine News", "date": "2026-08-27", "kSum": "8월26일 기준 최대 70척의 벌크선이 다뉴브강 술리나 운하 인근에서 우크라이나 항만 진입을 대기하며 곡물 선적이 지연됐다.", "eSum": "", "kImp": "곡물 수출 병목은 적하보험과 화물 지연·변질 리스크를 키운다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/queue-builds-off-danube-bottlenecks-slow-grain-exports-from-ukraine/"}, {"code": "INS", "title": "인도 해경, 침몰 벌크선 '오션위너' 구명정 발견…탑승자 없어", "eTitle": "Indian Coast Guard Finds Lost Bulker Ocean Winner's Lifeboat, No-one Aboard", "src": "Insurance Marine News", "date": "2026-08-27", "kSum": "벵골만에서 8월21일 전복·침몰한 벌크선 오션위너(Ocean Winner, IMO 9145530)의 생존자 수색이 이어지는 가운데 인도 해경이 인도 해군과 함께 빈 구명정을 발견했다. 선원 22명이 실종된 상태다.", "eSum": "", "kImp": "벌크선 전손과 인명 실종은 선체 전손보험금과 대형 배상 손해로 이어진다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/indian-coast-guard-finds-lost-bulkers-lifeboat-no-one-on-board/"}, {"code": "INS", "title": "벤티르, 북해 해상풍력 프로젝트 12개월 연기", "eTitle": "Ventyr Postpones North Sea Offshore Wind Project by 12 Months", "src": "Insurance Marine News", "date": "2026-08-27", "kSum": "노르웨이 에너지부가 JERA Nex(옛 파크윈드)와 재생에너지 개발사의 합작사인 벤티르(Ventyr)에 북해 해상풍력 프로젝트 12개월 연장을 승인했다.", "eSum": "", "kImp": "해상풍력 프로젝트 지연은 건설·운영 관련 해상보험 수요와 리스크 프로파일에 영향을 준다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/ventyr-postpones-north-sea-offshore-wind-project/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "국제P&I그룹, 남서태평양 니켈광 안전운송 서큘러 발행", "eTitle": "IG P&I Clubs Issue Circular on Safe Carriage of Nickel Ore in SW Pacific", "src": "IGP&I / Insurance Marine News", "date": "2026-08-27", "kSum": "국제P&I그룹(IG)이 인터카고(INTERCARGO)·록스버러와 공동으로 남서태평양(인도네시아·필리핀 등) 니켈광 수출과 관련한 액상화 위험을 경고하는 서큘러를 발행했다. 회원 선주에게 화물 수분함량 관리 등 위험 완화 권고사항을 제시했다.", "eSum": "", "kImp": "니켈광 액상화는 벌크선 전복·전손의 주요 원인으로, P&I 담보와 손해예방의 핵심 이슈다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/ig-circular-on-safe-carriage-of-nickel-ore-cargoes-in-south-western-pacific/"}, {"code": "PNI", "title": "IMO \"해적에 억류된 선원 90명 넘어\" 긴급 우려 표명", "eTitle": "IMO Notes More Than 90 Seafarers Now Held by Pirates", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "국제해사기구(IMO)가 8월24일 해적·무장강도에게 억류된 선원이 90명을 넘었다며 긴급 우려를 표명하고 선원 안전과 조속한 석방을 위한 국제 협력을 촉구했다.", "eSum": "", "kImp": "선원 억류 급증은 P&I의 선원·납치(K&R) 담보와 승선원 복지·안전 리스크를 부각한다.", "eImp": "", "url": "https://insurancemarinenews.com/insurance-marine-news/imo-notes-that-more-than-90-seafarers-are-now-being-held-by-pirates/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "美 해안경비대(USCG), 강선 선체 검사·수리 지침(NVIC 7-68) 개정", "eTitle": "USCG updates Navigation and Vessel Inspection Circular (NVIC) 7-68 on inspection and repair of steel hulls", "src": "USCG Maritime Commons", "date": "2026-08-22", "kSum": "미국 해안경비대(USCG)가 1968년 최초 발간된 '강선 선체의 검사·수리에 관한 지침'(NVIC 7-68)의 개정본을 발표했다. 개정본은 점식(피팅)·부식 수리에 대한 추가 지침을 담고, 국제선급연합(IACS) 권고 제47호 Part B(선박 수리·정비)를 허용 가능한 선박 수리 표준으로 반영했다. 관련 문의는 상선준수국(CVC)으로 안내됐다.", "eSum": "", "kImp": "강선 선체의 검사·수리 기준이 현대 조선·수리 기술과 IACS 표준에 맞춰 갱신되어, 선박 검사(PSC/CVC) 대응 및 선체 정비 실무의 직접적 참고 기준이 된다.", "eImp": "", "url": "https://www.news.uscg.mil/maritime-commons/Article/4580849/update-to-navigation-and-vessel-inspection-circular-nvic-7-68-notes-on-inspecti/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "로이드선급(LR), 호주 육군 상륙정 18척 선급 서비스 A$1,100만 수주", "eTitle": "Lloyd's Register wins A$11m classification role on 18 Australian Army landing craft", "src": "PortNews", "date": "2026-08-27", "kSum": "로이드선급(LR)이 오스탈 디펜스 오스트레일리아로부터 호주 육군용 중형 상륙정(Landing Craft Medium) 18척에 대한 A$1,100만(약 790만 달러) 규모의 선급 서비스 계약을 수주했다. 건조부터 인도까지 전 과정의 선급 검증을 맡으며 LR 인력이 헨더슨 조선소에 상주한다.", "eSum": "Lloyd's Register has won an A$11m ($7.9m) contract from Austal Defence Australia to provide classification services for 18 Landing Craft Medium vessels for the Australian Army, with LR personnel embedded at the Henderson shipyard throughout construction and delivery.", "kImp": "방위 신조 분야에서 선급의 독립 검증 역할 확대를 보여주는 대형 수주다.", "eImp": "A major award highlighting class societies' expanding independent-assurance role in naval newbuilding.", "url": "https://en.portnews.ru/news/396114/"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "SFL, 3억6300만 달러 규모 자동차운반선 추가 투자", "eTitle": "SFL Makes Fresh $363m Car Carrier Play", "src": "splash247", "date": "2026-08-27", "kSum": "SFL Corporation이 3억6300만 달러를 투입해 자동차운반선(PCTC) 확보에 다시 나섰다. 장기 용선 계약을 기반으로 한 신규 선대 투자로, 자산 포트폴리오를 자동차운반선 부문으로 확대하는 움직임이다.", "eSum": "", "kImp": "PCTC 선가와 용선료가 고공행진하는 가운데 선주들의 자산 배분이 자동차운반선으로 쏠리고 있음을 보여준다.", "eImp": "", "url": "https://splash247.com/sfl-makes-fresh-363m-car-carrier-play/"}, {"code": "COMM", "title": "베리타스, COSCO 조선소에 울트라막스 2척 추가 발주", "eTitle": "Veritas Books Fresh Ultramax Pair at COSCO Yard", "src": "splash247", "date": "2026-08-27", "kSum": "그리스 벌커 선주 베리타스 십매니지먼트가 저우산 소재 COSCO Shipping Heavy Industry에 울트라막스 벌커 2척을 추가 발주하며 2023년부터 이어온 신조 관계를 연장했다.", "eSum": "", "kImp": "중국 조선소로의 벌커 신조 발주가 꾸준히 유입되며 건화물 선대 교체·확장 수요가 견조함을 시사한다.", "eImp": "", "url": "https://splash247.com/veritas-books-fresh-ultramax-pair-at-cosco-yard/"}, {"code": "COMM", "title": "시너지, 헝리조선에 뉴캐슬막스 신조 발주 정황", "eTitle": "Seanergy Linked to Fresh Newcastlemax at Hengli", "src": "splash247", "date": "2026-08-27", "kSum": "시너지 마리타임이 중국 헝리(Hengli)조선에 대형 벌커(뉴캐슬막스) 신조를 추가 발주한 것으로 알려졌다. 빠른 속도로 진행 중인 선대 교체 전략의 연장선이다.", "eSum": "", "kImp": "케이프사이즈·뉴캐슬막스급 대형 벌커 신조가 이어지며 향후 선복 공급과 시장 밸런스에 영향을 줄 수 있다.", "eImp": "", "url": "https://splash247.com/seanergy-linked-to-fresh-newcastlemax-at-hengli/"}, {"code": "COMM", "title": "키필드, 2500만 달러 선박 인수로 준설시장 진출", "eTitle": "Keyfield Enters Dredging Market with $25m Vessel Acquisition", "src": "splash247", "date": "2026-08-27", "kSum": "말레이시아 해양지원선 선주 키필드 인터내셔널이 2500만 달러에 선박을 인수하며 준설(dredging) 시장에 새로 진입했다.", "eSum": "", "kImp": "해양지원선 선주들이 사업 다각화를 통해 신규 시장으로 진출하는 흐름을 보여주는 S&P 사례다.", "eImp": "", "url": "https://splash247.com/keyfield-enters-dredging-market-with-25m-vessel-acquisition/"}, {"code": "COMM", "title": "선박 해체(리사이클링) 시장, 회복세 진입", "eTitle": "Ship Recycling Market Gaining Positive Traction", "src": "hellenicshippingnews", "date": "2026-08-27", "kSum": "선박 해체(리사이클링) 시장이 긍정적 모멘텀을 얻고 있는 것으로 나타났다. 해체선 매입가격과 문의가 개선되며 시장 심리가 회복되고 있다는 분석이다.", "eSum": "", "kImp": "해체선가 회복은 노후선 처분 유인을 높여 선복 공급 조정과 운임 밸런스에 영향을 미치는 선행 지표다.", "eImp": "", "url": "https://www.hellenicshippingnews.com/ship-recycling-market-gaining-positive-traction/"}, {"code": "COMM", "title": "신조선 발주 활동 여전히 견조", "eTitle": "Newbuilding Activity Still Strong", "src": "hellenicshippingnews", "date": "2026-08-28", "kSum": "최근 신조선 발주 활동이 여전히 강한 흐름을 유지하고 있는 것으로 집계됐다. 다양한 선종에서 발주가 이어지며 조선소 수주잔량이 높은 수준을 지속하고 있다.", "eSum": "", "kImp": "높은 신조 발주와 선가는 향후 선복 공급 증가와 조선소 협상력 강화로 이어져 시장 전반에 영향을 준다.", "eImp": "", "url": "https://www.hellenicshippingnews.com/newbuilding-activity-still-strong/"}, {"code": "COMM", "title": "닝보-저우산항, 싱가포르 제치고 세계 2위 컨테이너항 등극", "eTitle": "Ningbo-Zhoushan Tops Singapore as World's Second Busiest Container Port", "src": "maritime-executive", "date": "2026-08-26", "kSum": "알파라이너 최신 순위에서 닝보-저우산 항만 복합단지가 싱가포르를 근소하게 앞질러 세계 2위 컨테이너항으로 올라섰다. 중국은 상위 10대 항만 중 6곳을 보유하게 됐다.", "eSum": "", "kImp": "미국의 관세 압박에도 중국 수출 물동량이 항만 처리량을 견인하며 글로벌 컨테이너 물류 지형의 변화를 보여준다.", "eImp": "", "url": "https://maritime-executive.com/article/ningbo-zhoushan-tops-singapore-as-world-s-second-busiest-container-port"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "MSC, 흑해 공격 지속에 노보로시스크 컨테이너 서비스 중단", "eTitle": "MSC Suspends Novorossiysk Container Service as Black Sea Attacks Continue", "src": "maritime-executive", "date": "2026-08-27", "kSum": "흑해에서의 공격이 컨테이너선으로 확대되자 MSC가 러시아 노보로시스크항에 대한 예약을 중단했다. 자사 선박 'MSC Ulsan III'가 8월 25일 드론 공격을 받았으며, 최근 Fesco 'Yanina' 침몰 등 컨테이너선 피격이 잇따르고 있다.", "eSum": "", "kImp": "흑해 전선이 상선·컨테이너선으로 확산되며 곡물·컨테이너 물류 차질과 보험·운임 리스크가 커지고 있다.", "eImp": "", "url": "https://maritime-executive.com/article/msc-suspends-novorossiysk-container-service-as-attacks-continue"}, {"code": "GEO", "title": "트럼프 행정부, 선박 나포용 '전시 포획법정' 부활 추진", "eTitle": "Trump Administration Moves to Revive Prize Courts for Vessel Seizures", "src": "maritime-executive", "date": "2026-08-26", "kSum": "트럼프 행정부가 나포 선박의 몰수 적법성을 신속 판단하는 19세기 제도인 '포획법정(prize court)' 부활을 추진 중이다. 법무부는 텍사스 남부지구(휴스턴)에 절차를 설치하는 방안을 검토하고 있으며, 이란·베네수엘라 봉쇄 관련 선박 나포에 활용될 전망이다.", "eSum": "", "kImp": "미국이 제재 대상 선박을 신속히 몰수·매각할 법적 수단을 확보하려는 것으로, 그림자 선단과 제재 회피 해운에 대한 압박이 크게 강화된다.", "eImp": "", "url": "https://maritime-executive.com/article/trump-administration-moves-to-revive-prize-courts-for-vessel-seizures"}, {"code": "GEO", "title": "이란 해상 원유 저장분, 5개월치로 급감", "eTitle": "Iran's Floating Oil Storage Shrinks to Five-Month Supply", "src": "maritime-executive", "date": "2026-08-26", "kSum": "미 재무부의 대이란 금융 압박('Operation Economic Outcast')과 봉쇄 속에서 이란의 해상 부유식 원유 저장분이 약 5개월치 수준으로 줄어든 것으로 분석됐다. 완전한 봉쇄가 아니어도 누적 효과가 나타나고 있다는 평가다.", "eSum": "", "kImp": "이란 원유 수출·저장 여력 축소는 제재 실효성과 유가, 그림자 선단 운영에 직접적 영향을 미치는 핵심 지표다.", "eImp": "", "url": "https://maritime-executive.com/editorials/iran-s-floating-oil-storage-shrinks-to-five-month-supply"}, {"code": "GEO", "title": "미 남부사령부, 68번째 마약선 치명 타격 완료", "eTitle": "U.S. Southern Command Completes 68th Lethal Drug Boat Strike", "src": "maritime-executive", "date": "2026-08-26", "kSum": "미 남부사령부가 카리브해 마약 밀수 의심 선박에 대한 68번째 공습을 수행해 누적 사망자가 약 227명에 이르렀다. 이번 타격으로 4명이 사망했다.", "eSum": "", "kImp": "미군의 해상 무력 사용 확대는 국제법·교전규칙 논란과 함께 서반구 해역의 군사화·항행 리스크를 키우고 있다.", "eImp": "", "url": "https://maritime-executive.com/article/u-s-southern-command-completes-68th-lethal-drug-boat-strike"}, {"code": "GEO", "title": "영국 해군, 아프리카의 뿔 인근 6개월간 해적 사건 25건 대응", "eTitle": "Royal Navy Reports 25 Piracy Incidents in Six Months off the Horn of Africa", "src": "maritime-executive", "date": "2026-08-26", "kSum": "영국 해군 주도 연합기동부대(CTF 151)가 지난 6개월간 인도양에서 20여 건의 해적 관련 사건에 개입했다고 밝혔다. 중동 분쟁 여파로 해적 활동이 10년 만에 최고 수준으로 재부상했다.", "eSum": "", "kImp": "호르무즈·홍해 위기와 맞물려 소말리아 해적이 재활성화되며 인도양 항로의 보안·전쟁위험 보험 부담이 가중되고 있다.", "eImp": "", "url": "https://maritime-executive.com/editorials/royal-navy-reports-25-piracy-incidents-in-six-months-off-the-horn-of-africa"}, {"code": "GEO", "title": "캐나다 서안 항만, 미국 넘어 교역 다변화 견인", "eTitle": "Canada's West Coast Ports Drive Trade Growth Beyond the U.S.", "src": "maritime-executive", "date": "2026-08-26", "kSum": "미국과의 무역전쟁이 심화되는 가운데 캐나다가 서안 항만을 통해 대미 의존도를 낮추고 국제 교역을 확대하고 있다는 연구가 발표됐다. 밴쿠버·프린스루퍼트 등이 대체 관문 역할을 강화하고 있다.", "eSum": "", "kImp": "미·캐나다 관세 갈등이 북미 물류 흐름을 재편하며 항만·항로 선택과 공급망 전략에 영향을 주고 있다.", "eImp": "", "url": "https://maritime-executive.com/article/canada-s-west-coast-ports-drive-trade-growth-beyond-the-u-s"}, {"code": "GEO", "title": "흑해 곡물 수출 급감에 밀 가격 급등", "eTitle": "Wheat Prices Soar as Russian and Ukrainian Grain Exports Plummet", "src": "maritime-executive", "date": "2026-08-27", "kSum": "흑해 분쟁으로 러시아·우크라이나 양측의 곡물 수출이 동시에 타격을 받으며 시카고 밀 선물이 이달 들어 18% 급등해 3년 만의 최고치를 기록했다. 항만·수송 차질이 가격 상승을 견인하고 있다.", "eSum": "", "kImp": "세계 양대 밀 수출지의 해상 물류 마비는 곡물 운임과 식량 안보, 벌커 시장에 광범위한 파급을 미친다.", "eImp": "", "url": "https://maritime-executive.com/article/wheat-prices-soar-as-russian-and-ukrainian-grain-exports-plummet"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "한화쉬핑(Hanwha Shipping), 신규 선대 첫 VLCC 명명", "eTitle": "Hanwha Shipping names first VLCC in its new fleet", "src": "PortNews", "date": "2026-08-27", "kSum": "한국 선주 한화쉬핑(Hanwha Shipping)이 자사 선대의 첫 초대형 원유운반선(VLCC)을 명명했다. 신생 선주로서 유조선 선대 구축을 본격화하고 있다. (선주·선박관리 커버리지, 헤드라인·요약 기준)", "eSum": "South Korean owner Hanwha Shipping has named the first VLCC in its fleet, marking the new entrant's push to build up its tanker fleet. (Owner/ship-management coverage; headline and summary basis.)", "kImp": "한화의 해운업 본격 진출과 대형 유조선 선대 확대를 보여준다.", "eImp": "Signals Hanwha's expansion into shipowning and large-tanker operations.", "url": "https://en.portnews.ru/news/396105/"}, {"code": "TW", "title": "CMB.TECH, 유조선 7척 매각… 매각 차익 3.59억 달러 전망", "eTitle": "CMB.TECH sells seven tankers with gains set to reach $359m", "src": "PortNews", "date": "2026-08-27", "kSum": "벨기에 선주 CMB.TECH가 유조선 7척을 매각하며 최대 3억5,900만 달러의 매각 차익이 예상된다고 밝혔다. 선대 재편과 자산 유동화를 진행하고 있다.", "eSum": "Belgian owner CMB.TECH is selling seven tankers, with expected gains of up to $359m, as it reshapes its fleet and realises asset value.", "kImp": "유조선 시황 강세 속 선주의 자산 매각·차익 실현 흐름을 보여준다.", "eImp": "Reflects owners realising gains through asset sales amid a strong tanker market.", "url": "https://en.portnews.ru/news/396118/"}, {"code": "TW", "title": "토름(TORM), 중국서 MR2 프로덕트 탱커 6척 신조 계약… 옵션 2척", "eTitle": "TORM signs for six MR2 newbuildings in China with two more on option", "src": "PortNews", "date": "2026-08-27", "kSum": "덴마크 유조선사 토름(TORM)이 중국 조선소에서 MR2 프로덕트 탱커 6척 신조 계약을 체결하고 추가 2척 옵션을 확보했다.", "eSum": "Danish tanker owner TORM has ordered six MR2 product tanker newbuildings in China, with options for two more.", "kImp": "프로덕트 탱커 선주의 선대 현대화 투자를 보여준다.", "eImp": "Shows a product-tanker owner investing in fleet renewal.", "url": "https://en.portnews.ru/news/396100/"}, {"code": "TW", "title": "터키 선주 바이락타르(Bayraktar), 15년 만에 中서 피더선 2+2척 발주", "eTitle": "Turkish owner Bayraktar orders 2+2 feeder boxships in China after 15-year gap", "src": "PortNews", "date": "2026-08-27", "kSum": "터키 선주 바이락타르(Bayraktar)가 15년 만의 신조로 중국 조선소에 피더 컨테이너선 2척을 발주하고 2척 옵션을 확보했다.", "eSum": "Turkish shipowner Bayraktar has returned to newbuilding after 15 years, ordering two feeder containerships in China with options for two more.", "kImp": "중소 선주의 컨테이너 피더선 신조 복귀 사례다.", "eImp": "A case of a mid-sized owner returning to feeder-boxship newbuilding.", "url": "https://en.portnews.ru/news/396110/"}, {"code": "TW", "title": "일본 선주 MOL, 풍력추진·AI 효율 기술 들고 COP31 참가", "eTitle": "Japan's MOL takes wind propulsion and AI efficiency tech to COP31 in Türkiye", "src": "PortNews", "date": "2026-08-26", "kSum": "일본 선주 MOL(상선미쓰이)이 튀르키예에서 열리는 COP31에 풍력추진과 AI 기반 운항 효율 기술을 선보인다. 자사 탈탄소 기술 성과를 국제 무대에서 소개한다.", "eSum": "Japanese owner MOL will showcase wind propulsion and AI-based operational efficiency technologies at COP31 in Türkiye, presenting its decarbonisation efforts on an international stage.", "kImp": "대형 선주의 탈탄소 기술 실증과 대외 홍보 전략을 보여준다.", "eImp": "Highlights a major owner's decarbonisation tech deployment and outreach.", "url": "https://en.portnews.ru/news/396066/"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "이란, '인도 탱커' 회항 주장하며 오만 회랑 '무통항' 선언", "eTitle": "Iran Claims to Turn Back 'Indian Tanker' Asserting Oman Corridor is Empty", "src": "maritime-executive", "date": "2026-08-27", "kSum": "이란 혁명수비대(IRGC)가 오만 해협 남측 항로에서 지난 24시간 통항이 전무했다며, 인도로 관리되는 LPG선 'Haana'를 경고 후 회항시켰다고 주장했다. 미 중부사령부는 8월 27일 기준 우회시킨 선박 수를 75척으로 늘렸다고 밝혔다.", "eSum": "", "kImp": "이란이 호르무즈 통제권 협상 지렛대로 통항 차단을 과시하고 미국은 봉쇄를 강화하며, 세계 최대 원유 관문의 마비 상태가 지속되고 있다.", "eImp": "", "url": "https://maritime-executive.com/article/iran-claims-to-turn-back-indian-tanker-asserting-oman-corridor-is-empty"}, {"code": "HOT", "title": "호르무즈 해협서 탱커, '미상 발사체' 피격", "eTitle": "Tanker Hit by 'Unknown Projectile' in Strait of Hormuz", "src": "maritime-executive", "date": "2026-08-26", "kSum": "영국 UKMTO에 따르면 8월 25일 밤 호르무즈 해협에서 탱커 1척이 미상 발사체에 피격됐다. 미국이 방어하는 오만 연안 회랑 통항 선박을 겨냥한 이란의 압박이 지속되고 있다는 신호다.", "eSum": "", "kImp": "중립 상선에 대한 공격이 반복되며 호르무즈 통항의 실질적 위험과 전쟁위험 보험료가 급등하고 있다.", "eImp": "", "url": "https://maritime-executive.com/article/tanker-hit-by-unknown-projectile-in-strait-of-hormuz"}, {"code": "HOT", "title": "호르무즈 해협 통항량 소폭 증가, 데이터 확인", "eTitle": "Shipping Traffic Through Strait of Hormuz Rises Slightly, Data Shows", "src": "gcaptain", "date": "2026-08-27", "kSum": "미·이란 대치와 이란·오만 협상이 이어지는 가운데 호르무즈 해협의 선박 통항량이 소폭 늘어난 것으로 데이터에 나타났다. Kpler 기준 수요일 통항 선박은 10척으로 화요일 8척에서 증가했다.", "eSum": "", "kImp": "통항량이 여전히 극도로 위축된 수준이어서 원유·LPG 수송 차질과 시장 불확실성이 지속되고 있음을 보여준다.", "eImp": "", "url": "https://gcaptain.com/shipping-traffic-through-strait-of-hormuz-rises-slightly-data-shows/"}, {"code": "HOT", "title": "트럼프 '임무 완수' 선언 속 호르무즈서 또 탱커 피격", "eTitle": "Tanker Hit in Strait of Hormuz as Trump Declares 'Mission Accomplished'", "src": "gcaptain", "date": "2026-08-27", "kSum": "트럼프 대통령이 이란에 대해 '임무 완수'를 선언한 가운데, 또 다른 탱커가 호르무즈 해협 통항 중 발사체에 피격됐다. 상선에 대한 위협이 여전함을 재확인시켰다.", "eSum": "", "kImp": "정치적 승리 선언과 현장의 지속적 공격 간 괴리가 커, 상선의 실제 안전 확보까지는 상당한 시간이 걸릴 것임을 시사한다.", "eImp": "", "url": "https://gcaptain.com/tanker-hit-in-strait-of-hormuz-as-trump-declares-mission-accomplished-in-iran/"}, {"code": "HOT", "title": "IRGC, '오만·이란, 호르무즈 통항료 합의' 주장", "eTitle": "IRGC Claims Oman and Iran Have Reached Deal on Hormuz Transit Fees", "src": "maritime-executive", "date": "2026-08-26", "kSum": "이란 혁명수비대(IRGC)가 오만과 호르무즈 해협 통항료 및 수역 관리에 관한 합의에 도달했다고 주장했다. 다만 오만 측은 로이터에 협상이 계속 진행 중이라고 밝혀 온도차를 드러냈다.", "eSum": "", "kImp": "통항료 부과 체계가 현실화되면 호르무즈 통과 비용 구조가 근본적으로 바뀔 수 있어 선주·화주의 주시 대상이다.", "eImp": "", "url": "https://maritime-executive.com/article/irgc-claims-that-oman-and-iran-have-reached-deal-on-hormuz-transit-fees"}, {"code": "HOT", "title": "이란·오만 합의 임박에도 호르무즈 통항 제한적…선사들 수에즈 복귀 검토", "eTitle": "Hormuz Transits Still Limited Even as Iran, Oman Near Deal; Carriers Eye Suez Return", "src": "hellenicshippingnews", "date": "2026-08-27", "kSum": "이란·오만이 호르무즈 운영 합의에 근접했음에도 실제 통항은 여전히 제한적인 것으로 나타났다. 일부 선사들은 위험 회피 차원에서 홍해·수에즈 항로 복귀를 저울질하고 있다.", "eSum": "", "kImp": "호르무즈 불확실성이 장기화되며 원유 물류가 대체 항로로 이동, 홍해·수에즈 항로의 물동량과 운임에도 연쇄 영향을 준다.", "eImp": "", "url": "https://www.hellenicshippingnews.com/hormuz-transits-still-limited-even-as-iran-oman-near-deal-carriers-eye-return-to-suez-route/"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "드람멘항, 선석 정렬 위해 Portchain Connect 도입", "eTitle": "Port of Drammen to implement Portchain Connect berth alignment system", "src": "Smart Maritime Network", "date": "2026-08-27", "kSum": "노르웨이 드람멘항(Port of Drammen)이 그린포트 서비스와 함께 선석 계획·정렬 지원을 위해 'Portchain Connect'를 도입한다. 선사-터미널 간 선석 일정 조율을 디지털화한다.", "eSum": "Norway's Port of Drammen, with terminal operator Greenport Services, is implementing Portchain Connect to support berth planning and alignment, digitalising berth-schedule coordination between lines and terminals.", "kImp": "항만-선사 데이터 연계형 선석관리 소프트웨어 확산을 보여준다.", "eImp": "Shows the spread of data-linked berth-management software between ports and carriers.", "url": "https://smartmaritimenetwork.com/2026/08/27/port-of-drammen-to-implement-berth-alignment-system/"}, {"code": "SYS", "title": "빅오션데이터, 지상 AIS 강화로 연안 선박 가시성 2.5배 확대", "eTitle": "BigOceanData more than doubles vessel visibility after terrestrial AIS upgrade", "src": "The Digital Ship", "date": "2026-08-27", "kSum": "해양 데이터 기업 빅오션데이터(BigOceanData)가 지상 AIS 업그레이드로 연안 해역 선박 추적 커버리지를 2.5배 확대했다. 선박 모니터링·리스크 관리 서비스의 가시성을 높인다.", "eSum": "Maritime data firm BigOceanData has upgraded its terrestrial AIS coverage, tracking 2.5 times more vessels in coastal waters and improving its monitoring and risk-management services.", "kImp": "선박 추적·모니터링 데이터 서비스의 품질 향상을 보여준다.", "eImp": "Shows quality improvement in vessel-tracking and monitoring data services.", "url": "https://thedigitalship.com/uncategorised/bigoceandata-tracks-2-5-times-more-vessels-after-terrestrial-ais-upgrade/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "최근 7일간 신규 소식이 확인되지 않았습니다", "eTitle": "No fresh items in the last 7 days", "src": "—", "date": "2026-08-28", "kSum": "이 기간 신선 기사가 확인되지 않았습니다. 다음 갱신 시 보완됩니다.", "eSum": "No fresh items in the last 7 days.", "kImp": "-", "eImp": "-", "url": "https://brightatsea-alt.github.io/maritime-daily-digest/"}]}]};